  { icon: <Home size={22} />, label: 'Home', onClick: () => alert('Home!') },
  { icon: <Search size={22} />, label: 'Search', onClick: () => alert('Search!') },
  { icon: <Settings size={22} />, label: 'Settings', onClick: () => alert('Settings!') },
];

export default function MyComponent() {
  return (
    <MagnificationDock 
      items={items}
      panelHeight={68}
      baseItemSize={50}
      magnification={80}
    />
  );
}
```
